Q: Using std::meta::members_of() on a namespace A: <p><code>members_of</code> returns a <code>std::vector</code>. This can be <em>part</em> of a constant expression as long as it is destroyed before the constant expression ends, but cannot be the entire constant expression because the elements are not deallocated.</p>
<p>Use <code>std::define_static_array</code> to get an static storage duration array instead of a vector referring to dynamic storage duration elements:</p>
<pre class="lang-cpp prettyprint-override"><code>int main() {
    constexpr auto ns_refl = ^^std;
    constexpr auto ctx = std::meta::access_context::unchecked();
    constexpr auto members = std::define_static_array(std::meta::members_of(ns_refl, ctx));
    template for (constexpr auto&amp; member : auto(members)) {
        if constexpr (std::meta::has_identifier(member))
            std::cout &lt;&lt; std::meta::identifier_of(member) &lt;&lt; '\n';
    }
}
</code></pre>
